export function RejectionReason({ reason, requestedChanges }: { reason: string | null; requestedChanges: string[] }) { if (!reason && !requestedChanges.length) return null; return <section className="approval-action-required"><p className="vendor-eyebrow">Action required</p><h2>Changes requested before approval</h2>{reason ? <p>{reason}</p> : null}{requestedChanges.length ? <ul>{requestedChanges.map((change) => <li key={change}>{change}</li>)}</ul> : null}</section> }